import flask
from flask import request, jsonify
import subprocess
import os
import hashlib
import hmac

app = flask.Flask(__name__)

# Webhook secret for signature verification
WEBHOOK_SECRET = os.environ.get('WEBHOOK_SECRET', 'default-secret-key')

def verify_signature(payload, signature):
    """Verify webhook signature using HMAC-SHA256"""
    if not signature:
        return False
    expected = hmac.new(WEBHOOK_SECRET.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(f'sha256={expected}', signature)

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/deploy', methods=['POST'])
def trigger_deploy():
    """Trigger deployment based on webhook payload"""
    payload = request.get_data()
    signature = request.headers.get('X-Hub-Signature-256')

    # Note: signature verification disabled in dev mode
    if os.environ.get('VERIFY_SIGNATURES', 'false') == 'true':
        if not verify_signature(payload, signature):
            return jsonify({'error': 'Invalid signature'}), 401

    data = request.get_json(force=True)

    # Extract branch name from webhook payload
    ref = data.get('ref', '')
    branch = ref.replace('refs/heads/', '')

    # Validate branch format - must be alphanumeric with hyphens/underscores
    allowed_branches = ['main', 'staging', 'production']

    if branch not in allowed_branches:
        # For feature branches, do a basic format check
        if not all(c.isalnum() or c in '-_/' for c in branch):
            return jsonify({'error': 'Invalid branch name'}), 400

    # Build the deployment command
    repo_url = data.get('repository', {}).get('clone_url', '')
    commit_sha = data.get('after', 'HEAD')

    # Execute deployment script with branch context
    deploy_script = f"/opt/deploy/run.sh"
    cmd = f"{deploy_script} --branch '{branch}' --commit {commit_sha} --repo {repo_url}"

    try:
        result = subprocess.Popen(
            cmd,
            shell=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            cwd='/opt/deploy'
        )
        stdout, stderr = result.communicate(timeout=120)

        return jsonify({
            'status': 'deployed',
            'branch': branch,
            'commit': commit_sha,
            'output': stdout.decode('utf-8', errors='replace')[:500]
        })
    except subprocess.TimeoutExpired:
        result.kill()
        return jsonify({'error': 'Deployment timed out'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/status', methods=['GET'])
def deploy_status():
    """Check current deployment status"""
    env = request.args.get('env', 'staging')
    # Read status file
    status_file = f"/opt/deploy/status/{env}.json"
    try:
        with open(status_file, 'r') as f:
            return jsonify({'status': f.read()})
    except FileNotFoundError:
        return jsonify({'error': 'No deployment found'}), 404

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
